--

CREATE FUNCTION public.add_creator_as_org_member() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  creator_id uuid;
begin
  creator_id := coalesce(new.owner_id, auth.uid());
  if creator_id is not null then
    insert into public.organization_members (user_id, organization_id, role, is_paid_member, status)
    values (creator_id, new.id, 'owner', true, 'active')
    on conflict (organization_id, user_id) do nothing;
  end if;
  return new;
end;
$$;


