--

CREATE FUNCTION public.auto_set_access_mode_from_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- If plan tier is set, set access mode to paid
  if new.plan_tier_key is not null then
    if new.plan_tier_key like 'creator_%' then
      new.access_mode_key := 'paid_creator';
    else
      new.access_mode_key := 'paid_client';
    end if;
  end if;
  
  return new;
end;
$$;


--
-- Name: calculate_next_run(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_next_run(cron_expression text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
      DECLARE
        parts text[];
        minute_val int;
        hour_val int;
        dom_val text;
        month_val text;
        dow_val text;
        now_ts timestamptz;
        next_ts timestamptz;
        candidate timestamptz;
      BEGIN
        IF cron_expression IS NULL OR cron_expression = '' THEN
          RETURN NOW() + interval '1 hour';
        END IF;

        parts := regexp_split_to_array(trim(cron_expression), E'\\s+');
        IF array_length(parts, 1) < 5 THEN
          RETURN NOW() + interval '1 hour';
        END IF;

        minute_val := CASE WHEN parts[1] = '*' THEN -1 ELSE parts[1]::int END;
        hour_val := CASE WHEN parts[2] = '*' THEN -1 ELSE parts[2]::int END;
        dom_val := parts[3];
        month_val := parts[4];
        dow_val := parts[5];

        now_ts := NOW();
        next_ts := date_trunc('minute', now_ts) + interval '1 minute';

        IF minute_val >= 0 AND hour_val >= 0 AND dom_val = '*' AND month_val = '*' AND dow_val = '*' THEN
          candidate := date_trunc('day', now_ts) + make_time(hour_val, minute_val, 0);
          IF candidate <= now_ts THEN
            candidate := candidate + interval '1 day';
          END IF;
          RETURN candidate;
        END IF;

        IF minute_val = -1 AND hour_val = -1 AND dom_val = '*' AND month_val = '*' AND dow_val = '*' THEN
          RETURN NOW() + interval '1 hour';
        END IF;

        IF minute_val >= 0 AND hour_val = -1 AND dom_val = '*' AND month_val = '*' AND dow_val = '*' THEN
          candidate := date_trunc('hour', now_ts) + (minute_val || ' minutes')::interval;
          IF candidate <= now_ts THEN
            candidate := candidate + interval '1 hour';
          END IF;
          RETURN candidate;
        END IF;

        IF minute_val >= 0 AND hour_val >= 0 AND dom_val = '*' AND month_val = '*' AND dow_val != '*' THEN
          DECLARE
            target_dow int := dow_val::int;
            current_dow int;
          BEGIN
            current_dow := EXTRACT(DOW FROM now_ts)::int;
            candidate := date_trunc('day', now_ts) + make_time(hour_val, minute_val, 0);
            IF current_dow = target_dow AND candidate > now_ts THEN
              RETURN candidate;
            END IF;
            candidate := candidate + (((target_dow - current_dow + 7) % 7) || ' days')::interval;
            RETURN candidate;
          END;
        END IF;

        -- NEW: monthly on a fixed day-of-month (e.g. "0 6 1 * *" = 1st of
        -- month at 06:00), dow = '*'.
        IF minute_val >= 0 AND hour_val >= 0 AND dom_val != '*' AND month_val = '*' AND dow_val = '*' THEN
          DECLARE
            target_dom int := dom_val::int;
          BEGIN
            candidate := date_trunc('month', now_ts) + ((target_dom - 1) || ' days')::interval + make_time(hour_val, minute_val, 0);
            IF candidate <= now_ts THEN
              candidate := date_trunc('month', now_ts + interval '1 month') + ((target_dom - 1) || ' days')::interval + make_time(hour_val, minute_val, 0);
            END IF;
            RETURN candidate;
          END;
        END IF;

        RETURN NOW() + interval '1 hour';
      END;
      $$;


--
-- Name: can_add_agent(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_add_agent(p_client_id uuid, p_agent_type text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_plan_key text;
  v_access_mode text;
  v_current_vertical_count int;
  v_current_custom_count int;
  v_max_vertical int;
  v_max_custom int;
  v_org_id uuid;
begin
  -- Get client's plan and access mode
  select plan_tier_key, access_mode_key, organization_id
  into v_plan_key, v_access_mode, v_org_id
  from clients
  where id = p_client_id;
  
  -- Free tiers blocked
  if v_access_mode in ('free_onboarding', 'free_affiliate') then
    return false;
  end if;
  
  -- No plan tier → blocked
  if v_plan_key is null then
    return false;
  end if;
  
  -- Get entitlements
  select max_vertical_agents, max_custom_agents
  into v_max_vertical, v_max_custom
  from tier_entitlements
  where plan_key = v_plan_key;
  
  -- Count current vertical agents
  select count(*) into v_current_vertical_count
  from organization_agents oa
  join agents a on a.id = oa.agent_id
  join agent_definitions ad on ad.slug = a.slug
  where oa.org_id = v_org_id
    and ad.is_master = false;
  
  -- Count current custom agents
  select count(*) into v_current_custom_count
  from organization_agents oa
  join agents a on a.id = oa.agent_id
  join agent_definitions ad on ad.slug = a.slug
  where oa.org_id = v_org_id
    and ad.is_master = true;
  
  -- Check caps
  if p_agent_type = 'vertical' then
    return v_current_vertical_count < v_max_vertical;
  elsif p_agent_type = 'custom' then
    return v_current_custom_count < v_max_custom;
  else
    return false;
  end if;
end;
$$;


--
-- Name: can_add_swarm(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_add_swarm(p_client_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_plan_key text;
  v_access_mode text;
  v_current_swarm_count int;
  v_max_swarm int;
  v_org_id uuid;
begin
  select plan_tier_key, access_mode_key, organization_id
  into v_plan_key, v_access_mode, v_org_id
  from clients
  where id = p_client_id;
  
  -- Free tiers blocked
  if v_access_mode in ('free_onboarding', 'free_affiliate') then
    return false;
  end if;
  
  if v_plan_key is null then
    return false;
  end if;
  
  select max_swarm_capacity into v_max_swarm
  from tier_entitlements
  where plan_key = v_plan_key;
  
  select count(*) into v_current_swarm_count
  from agent_swarms
  where organization_id = v_org_id;
  
  return v_current_swarm_count < v_max_swarm;
end;
$$;


--
-- Name: check_entitlement(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_entitlement(org_uuid uuid, entitlement_key_param text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'feature_key', e.feature_key,
    'limit_value', e.limit_value,
    'is_enabled', e.is_enabled,
    'usage_count', COALESCE(e.usage_count, 0),
    'source_type', e.source_type,
    'organization_id', e.organization_id
  ) INTO result
  FROM public.entitlements e
  WHERE e.organization_id = org_uuid
    AND e.feature_key = entitlement_key_param;
  
  IF result IS NULL THEN
    RETURN jsonb_build_object(
      'feature_key', entitlement_key_param,
      'limit_value', 0,
      'is_enabled', false,
      'usage_count', 0,
      'source_type', 'default',
      'organization_id', org_uuid
    );
  END IF;
  
  RETURN result;
END;
$$;


