--
-- Name: claim_queue_jobs(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_queue_jobs(queue text, batch_size integer, worker text) RETURNS SETOF public.queue_jobs
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$

update queue_jobs
set
status='claimed',
worker_id=worker,
started_at=now()

where id in(

select id
from queue_jobs

where
queue_name=queue
and status='pending'

order by scheduled_at

limit batch_size

for update skip locked

)

returning *;

$$;


--
-- Name: claim_workflow_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_workflow_job() RETURNS SETOF public.queue_jobs
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN

RETURN QUERY
UPDATE public.queue_jobs AS q
SET
status='running',
worker_id=gen_random_uuid()::text,
locked_at=now()
WHERE q.id=(
SELECT jq.id
FROM public.queue_jobs jq
WHERE jq.status IN ('pending','retrying')
AND jq.scheduled_at<=now()
ORDER BY jq.scheduled_at ASC
FOR UPDATE SKIP LOCKED
LIMIT 1
)
RETURNING q.*;

END;
$$;


--
-- Name: claim_workflow_job(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_workflow_job(worker text) RETURNS TABLE(id uuid, workflow_run_id uuid, node_run_id uuid, attempt integer, max_attempts integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  job_record record;
begin
  select * into job_record
  from queue_jobs
  where status = 'pending' and queue_name = 'workflow'
  order by scheduled_at
  limit 1
  for update skip locked;

  if job_record.id is null then
    return;
  end if;

  update queue_jobs
  set status = 'running', worker_id = worker, locked_at = now()
  where queue_jobs.id = job_record.id;

  return query
  select job_record.id, job_record.workflow_run_id, job_record.node_run_id,
         job_record.attempt, job_record.max_attempts;
end;
$$;


--
-- Name: creator_can_sell_to_client(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.creator_can_sell_to_client(p_creator_client_id uuid, p_target_client_tier text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_creator_plan_key text;
  v_can_sell boolean;
begin
  -- Get creator's plan tier
  select plan_tier_key into v_creator_plan_key
  from clients
  where id = p_creator_client_id;
  
  -- No plan tier → blocked
  if v_creator_plan_key is null then
    return false;
  end if;
  
  -- Check sales eligibility
  select can_sell_to_client into v_can_sell
  from sales_eligibility
  where creator_plan_key = v_creator_plan_key
    and client_plan_key = p_target_client_tier;
  
  return coalesce(v_can_sell, false);
end;
$$;


--
-- Name: decrement_entitlement_usage(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_entitlement_usage(org_uuid uuid, entitlement_key_param text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  result jsonb;
BEGIN
  UPDATE public.entitlements e
  SET usage_count = GREATEST(COALESCE(e.usage_count, 1) - 1, 0),
      updated_at = now()
  WHERE e.organization_id = org_uuid
    AND e.feature_key = entitlement_key_param
  RETURNING jsonb_build_object(
    'feature_key', e.feature_key,
    'usage_count', e.usage_count,
    'limit_value', e.limit_value
  ) INTO result;
  
  RETURN result;
END;
$$;


--
-- Name: decrement_entitlement_usage_custom(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decrement_entitlement_usage_custom(org_uuid uuid, entitlement_key_param text, decrement_by integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  result jsonb;
BEGIN
  UPDATE public.entitlements e
  SET usage_count = GREATEST(COALESCE(e.usage_count, 0) - decrement_by, 0),
      updated_at = now()
  WHERE e.organization_id = org_uuid
    AND e.feature_key = entitlement_key_param
  RETURNING jsonb_build_object(
    'feature_key', e.feature_key,
    'usage_count', e.usage_count,
    'limit_value', e.limit_value
  ) INTO result;
  
  RETURN result;
END;
$$;


