--
-- Name: generate_org_slug(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_org_slug(input text, unique_suffix text DEFAULT ''::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT lower(regexp_replace(substring(
    CASE WHEN unique_suffix = '' THEN input
         ELSE input || '-' || unique_suffix
    END
  from 1 for 56), '[^a-zA-Z0-9-]', '-', 'g'));
$$;


