--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'extensions,public'
    AS $$
BEGIN
  INSERT INTO public.users (id, email, full_name, role, created_at, updated_at)
  VALUES (
    NEW.id,
    NEW.email,
    NEW.raw_user_meta_data ->> 'full_name',
    COALESCE(NEW.raw_user_meta_data ->> 'role', 'client'),
    NOW(),
    NOW()
  );
  RETURN NEW;
END;
$$;


--
-- Name: increment_entitlement_usage(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_entitlement_usage(org_uuid uuid, entitlement_key_param text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  result jsonb;
BEGIN
  UPDATE public.entitlements e
  SET usage_count = COALESCE(e.usage_count, 0) + 1,
      updated_at = now()
  WHERE e.organization_id = org_uuid
    AND e.feature_key = entitlement_key_param
  RETURNING jsonb_build_object(
    'feature_key', e.feature_key,
    'usage_count', e.usage_count,
    'limit_value', e.limit_value,
    'within_limit', e.usage_count <= e.limit_value
  ) INTO result;
  
  RETURN result;
END;
$$;


--
-- Name: increment_entitlement_usage_custom(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_entitlement_usage_custom(org_uuid uuid, entitlement_key_param text, increment_by integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  result jsonb;
BEGIN
  UPDATE public.entitlements e
  SET usage_count = COALESCE(e.usage_count, 0) + increment_by,
      updated_at = now()
  WHERE e.organization_id = org_uuid
    AND e.feature_key = entitlement_key_param
  RETURNING jsonb_build_object(
    'feature_key', e.feature_key,
    'usage_count', e.usage_count,
    'limit_value', e.limit_value,
    'within_limit', e.usage_count <= e.limit_value
  ) INTO result;
  
  RETURN result;
END;
$$;


--
-- Name: increment_merge_counter(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_merge_counter(p_workflow_run_id uuid, p_node_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  insert into workflow_merge_counters (workflow_run_id, node_id, arrived_count, required_count, updated_at)
  values (
    p_workflow_run_id,
    p_node_id,
    1,
    (select count(*) from workflow_edges where to_node_id = p_node_id),
    now()
  )
  on conflict (workflow_run_id, node_id)
  do update set arrived_count = workflow_merge_counters.arrived_count + 1, updated_at = now();
end;
$$;


