--
-- Name: merge_ready(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_ready(p_workflow_run_id uuid, p_node_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  ready boolean;
begin
  select arrived_count >= required_count into ready
  from workflow_merge_counters
  where workflow_run_id = p_workflow_run_id and node_id = p_node_id;

  return coalesce(ready, false);
end;
$$;


