--

CREATE FUNCTION public.omnigrid_intelligence_system_trg() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  select name
    into new.lens_name
    from omnigrid_system_lenses
    where key = new.lens_key
    limit 1;

  if new.domain_key is not null then
    select name
      into new.domain_name
      from omnigrid_system_domains
      where key = new.domain_key
      limit 1;
  end if;

  return new;
end;
$$;


--
-- Name: onboard_client_provision_defaults(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.onboard_client_provision_defaults(p_client_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_plan_key text;
  v_org_id uuid;
  v_max_vertical int;
  v_default_vertical_agents text[];
  v_i int := 0;
  current_agent text;
begin
  -- Get client's plan and org
  select plan_tier_key, organization_id
  into v_plan_key, v_org_id
  from clients
  where id = p_client_id;
  
  if v_plan_key is null then
    return;
  end if;
  
  -- Get entitlements
  select max_vertical_agents into v_max_vertical
  from tier_entitlements
  where plan_key = v_plan_key;
  
  -- Default vertical agents by tier
  case v_plan_key
    when 'client_founder' then
      v_default_vertical_agents := array[
        'luxury_acquisition_agent',
        're_concierge_agent',
        'showing_optimization_agent'
      ];
    when 'client_teams' then
      v_default_vertical_agents := array[
        'luxury_acquisition_agent',
        're_concierge_agent',
        'showing_optimization_agent', 
        'deal_flow_agent',
        'market_intelligence_agent'
      ];
    when 'creator_studio' then
      v_default_vertical_agents := array[
        'content_offer_generator_agent'
      ];
    when 'creator_premium' then
      v_default_vertical_agents := array[
        'content_offer_generator_agent',
        'monetization_agent',
        'campaigns_agent'
      ];
    when 'creator_concierge' then
      v_default_vertical_agents := array[
        'content_offer_generator_agent',
        'monetization_agent',
        'campaigns_agent',
        'luxury_concierge_agent',
        'relationship_intelligence_agent'
      ];
    else
      v_default_vertical_agents := array[]::text[];
  end case;
  
  -- Insert default vertical agents
  foreach current_agent in array v_default_vertical_agents
  loop
    v_i := v_i + 1;
    if v_i > v_max_vertical then
      exit;
    end if;
    
    insert into organization_agents (org_id, agent_id)
    select v_org_id, a.id
    from agents a
    where a.slug = current_agent
      and not exists (
        select 1 from organization_agents oa2
        where oa2.org_id = v_org_id and oa2.agent_id = a.id
      )
    on conflict do nothing;
  end loop;
end;
$$;


