--
-- Name: provision_organization_for_tier(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_organization_for_tier(p_user_id uuid, p_tier_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_tier record;
  v_te record;
  v_display_name text;
  v_org_slug text;
  v_new_org_id uuid;
  v_user auth.users%rowtype;
begin
  if auth.uid() is distinct from p_user_id and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'not authorized to provision membership for this user';
  end if;

  select * into v_tier from public.membership_tiers where key = p_tier_key;
  if not found then
    raise exception 'unknown membership_tier key: %', p_tier_key;
  end if;

  if not coalesce(v_tier.is_organization, false) then
    -- ROUND 16 (item D1): Creator tiers (Studio/Premium/Concierge) get a
    -- free, user-scoped Core OS activation even though they don't get an
    -- organization. Personal and Affiliate tiers fall through this branch
    -- untouched and get nothing, matching Zuri's explicit instruction that
    -- the $299 Core value was only ever meant for Business/Creator plans.
    if v_tier.tier_type = 'creator' then
      insert into public.os_activations (user_id, item_type, item_key, tier_level, state, source)
      values (p_user_id, 'os_package', 'core_os', 'standard', 'active', 'included_free')
      on conflict do nothing;
    end if;
    return null;
  end if;

  select * into v_user from auth.users where id = p_user_id;
  v_display_name := coalesce(v_user.raw_user_meta_data->>'full_name', split_part(v_user.email, '@', 1), 'User');
  v_org_slug := public.generate_org_slug(v_display_name, substring(p_user_id::text from 25));

  insert into public.organizations (name, slug, owner_id, status, timezone)
  values (
    v_display_name,
    v_org_slug,
    p_user_id,
    'active',
    coalesce(v_user.raw_user_meta_data->>'timezone', 'UTC')
  )
  returning id into v_new_org_id;

  insert into public.memberships (organization_id, membership_tier_id, user_id, status)
  values (v_new_org_id, v_tier.id, p_user_id, 'active');

  select * into v_te from public.tier_entitlements where plan_key = p_tier_key;

  insert into public.entitlements (organization_id, feature_key, limit_value, source_type) values
    (v_new_org_id, 'agent_slots', coalesce(v_te.max_agents, 10), 'default'),
    (v_new_org_id, 'swarm_slots', coalesce(v_te.max_swarms, 5), 'default'),
    (v_new_org_id, 'workflow_runs_monthly', coalesce(v_te.max_workflow_runs_monthly, 1000), 'default'),
    (v_new_org_id, 'api_calls_monthly', coalesce(v_te.max_api_calls_monthly, 10000), 'default'),
    (v_new_org_id, 'storage_gb', coalesce(v_te.max_storage_gb, 5), 'default');

  insert into public.os_activations (organization_id, item_type, item_key, tier_level, state, source)
  values (v_new_org_id, 'os_package', 'core_os', 'standard', 'active', 'included_free');

  return v_new_org_id;
end;
$_$;


--
-- Name: retry_workflow_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_workflow_job(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$

DECLARE

v_attempt integer;

v_max integer;

BEGIN

SELECT

attempt,

max_attempts

INTO

v_attempt,

v_max

FROM queue_jobs

WHERE id=p_job_id;

IF v_attempt<v_max THEN

UPDATE queue_jobs

SET

attempt=attempt+1,

status='retrying',

scheduled_at=

now()+

((5*power(2,v_attempt))||' seconds')::interval

WHERE id=p_job_id;

ELSE

UPDATE queue_jobs

SET status='failed'

WHERE id=p_job_id;

END IF;

END;

$$;


--
-- Name: ris_check(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ris_check(entity uuid, type text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_status text;
BEGIN

  SELECT status
  INTO v_status
  FROM ris_registry
  WHERE entity_id = entity
    AND entity_type = type
  ORDER BY issued_at DESC
  LIMIT 1;

  IF v_status = 'verified' THEN
    RETURN true;
  END IF;

  RETURN false;

END;
$$;


--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


