--
-- Name: sync_plan_tiers_to_entitlements(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_plan_tiers_to_entitlements() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into tier_entitlements (
      plan_key,
      max_vertical_agents,
      max_custom_agents,
      max_swarm_capacity,
      max_workflows,
      max_memory_gbs,
      can_use_wealth_addon,
      can_use_luxury_hospitality_addon,
      can_use_creator_commerce_addon
    )
    values (
      new.key,
      new.max_vertical_agents,
      new.max_custom_agents,
      new.max_swarm_capacity,
      new.max_workflows,
      new.max_memory_gbs,
      case when new.key = 'client_enterprise' then true else false end,
      case when new.key in ('client_enterprise', 'client_teams') then true else false end,
      case when new.key in ('client_enterprise', 'client_teams') then true else false end
    )
    on conflict (plan_key) do nothing;

    return new;
  end if;

  if tg_op = 'UPDATE' then
    update tier_entitlements
    set max_vertical_agents = new.max_vertical_agents,
        max_custom_agents = new.max_custom_agents,
        max_swarm_capacity = new.max_swarm_capacity,
        max_workflows = new.max_workflows,
        max_memory_gbs = new.max_memory_gbs,
        can_use_wealth_addon = case when new.key = 'client_enterprise' then true else false end,
        can_use_luxury_hospitality_addon = case when new.key in ('client_enterprise', 'client_teams') then true else false end,
        can_use_creator_commerce_addon = case when new.key in ('client_enterprise', 'client_teams') then true else false end,
        updated_at = now()
    where plan_key = new.key;

    return new;
  end if;

  return new;
end;
$$;


