--
-- Name: validate_onboarding_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_onboarding_access(p_client_id uuid) RETURNS TABLE(is_valid boolean, access_mode text, plan_tier text, can_see_intelligence boolean, can_see_agents boolean, can_use_swarms boolean, error_message text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_access_mode_key text;
  v_plan_tier_key text;
  v_access_record record;
begin
  -- Get client's access mode and plan tier
  select access_mode_key, plan_tier_key
  into v_access_mode_key, v_plan_tier_key
  from clients
  where id = p_client_id;
  
  -- Case 1: No access mode set
  if v_access_mode_key is null then
    return query select
      false,
      null::text,
      null::text,
      false,
      false,
      false,
      'Access mode not set for this client';
    return;
  end if;
  
  -- Get access mode record
  select * into v_access_record
  from client_access_modes
  where key = v_access_mode_key;
  
  if not found then
    return query select
      false,
      v_access_mode_key,
      v_plan_tier_key,
      false,
      false,
      false,
      'Invalid access mode key';
    return;
  end if;
  
  -- Return access mode permissions
  return query select
    true,
    v_access_mode_key,
    v_plan_tier_key,
    v_access_record.can_see_intelligence,
    v_access_record.can_see_agents,
    v_access_record.can_use_swarms,
    null::text;
end;
$$;


