--
-- Name: affiliate_links_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.affiliate_links_readable WITH (security_invoker='on') AS
 SELECT al.id,
    al.code,
    al.label,
    al.status,
    COALESCE(u.email, o.name) AS owner,
    ci.name AS target_item_name,
    al.target_url,
    al.clicks_count,
    al.conversions_count,
    al.created_at,
    al.owner_user_id,
    al.owner_organization_id,
    al.target_catalog_item_id
   FROM (((public.affiliate_links al
     LEFT JOIN public.users u ON ((u.id = al.owner_user_id)))
     LEFT JOIN public.organizations o ON ((o.id = al.owner_organization_id)))
     LEFT JOIN public.catalog_items ci ON ((ci.id = al.target_catalog_item_id)));


