--
-- Name: agent_catalog; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.agent_catalog WITH (security_invoker='true') AS
 SELECT id,
    agent_id,
    agent_name AS name,
    slug,
    tagline,
    description,
    long_description,
    agent_type,
    role_type,
    vertical,
    canonical_vertical_slug,
    canonical_template,
    is_master,
    is_bridge,
    agent_type AS agent_type_key,
    primary_system,
    secondary_system,
    tertiary_system,
    high_level_archetype,
    capabilities,
    tools,
    connectors,
    triggers,
    outputs,
    model,
    autonomy_level,
    authority_level,
    risk_level,
    memory_enabled,
    autonomous_enabled,
    orchestration_enabled,
    orchestration_mode,
    health_status,
    evolution_status,
    mas_score,
    mas_vector,
    is_system_agent,
    is_published,
    marketplace_visible,
    required_tier,
    catalog_status,
    metadata,
        CASE
            WHEN ((icon IS NOT NULL) AND (array_length(icon, 1) > 0)) THEN icon[1]
            ELSE NULL::text
        END AS icon,
    mas_category AS category,
    COALESCE(is_published, false) AS is_active,
    created_at,
    updated_at
   FROM public.agents a
  WHERE (deleted_at IS NULL);


