--
-- Name: catalog_items_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.catalog_items_readable WITH (security_invoker='on') AS
 SELECT ci.id,
    ci.sku,
    ci.name AS item_name,
    ct.name AS catalog_type_name,
    cc.name AS category_name,
    ci.pricing_type,
    ci.base_price,
    ci.currency,
    ci.active,
    ci.featured,
    org.name AS seller_organization_name,
    creator.email AS created_by_email,
    ci.applicable_os,
    ci.created_at,
    ci.updated_at
   FROM ((((public.catalog_items ci
     LEFT JOIN public.catalog_types ct ON ((ct.id = ci.catalog_type_id)))
     LEFT JOIN public.catalog_categories cc ON ((cc.id = ci.category_id)))
     LEFT JOIN public.organizations org ON ((org.id = ci.organization_id)))
     LEFT JOIN public.users creator ON ((creator.id = ci.created_by)));


--
-- Name: catalog_pricing; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalog_pricing (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    catalog_item_id uuid NOT NULL,
    price numeric(10,2),
    sale_price numeric(10,2),
    currency text DEFAULT 'USD'::text,
    billing_type text,
    billing_interval text,
    trial_days integer DEFAULT 0,
    effective_from timestamp with time zone DEFAULT now(),
    effective_to timestamp with time zone,
    active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    charge_role text DEFAULT 'standard'::text NOT NULL,
    notes text,
    CONSTRAINT catalog_pricing_charge_role_check CHECK ((charge_role = ANY (ARRAY['standard'::text, 'setup_fee'::text, 'recurring'::text])))
);


--
-- Name: catalog_pricing_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.catalog_pricing_readable WITH (security_invoker='on') AS
 SELECT cp.id,
    ci.name AS item_name,
    ci.sku,
    cp.price,
    cp.sale_price,
    cp.currency,
    cp.billing_type,
    cp.billing_interval,
    cp.charge_role,
    cp.trial_days,
    cp.active,
    cp.effective_from,
    cp.effective_to,
    cp.notes,
    cp.catalog_item_id,
    cp.created_at
   FROM (public.catalog_pricing cp
     LEFT JOIN public.catalog_items ci ON ((ci.id = cp.catalog_item_id)));


