--

CREATE TABLE public.catalog_purchases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    catalog_item_id uuid NOT NULL,
    buyer_user_id uuid,
    buyer_organization_id uuid,
    seller_organization_id uuid,
    amount numeric NOT NULL,
    currency text DEFAULT 'USD'::text NOT NULL,
    commission_percent numeric,
    application_fee_amount numeric,
    seller_net_amount numeric,
    stripe_payment_intent_id text,
    stripe_checkout_session_id text,
    status text DEFAULT 'pending'::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    seller_user_id uuid,
    CONSTRAINT catalog_purchases_seller_not_both_check CHECK ((NOT ((seller_organization_id IS NOT NULL) AND (seller_user_id IS NOT NULL))))
);


--
-- Name: catalog_purchases_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.catalog_purchases_readable WITH (security_invoker='on') AS
 SELECT cp.id,
    ci.name AS item_name,
    buyer_user.email AS buyer_email,
    buyer_org.name AS buyer_organization_name,
    seller_org.name AS seller_organization_name,
    seller_user.email AS seller_user_email,
    cp.amount,
    cp.currency,
    cp.commission_percent,
    cp.seller_net_amount,
    cp.status,
    cp.created_at
   FROM (((((public.catalog_purchases cp
     LEFT JOIN public.catalog_items ci ON ((ci.id = cp.catalog_item_id)))
     LEFT JOIN public.users buyer_user ON ((buyer_user.id = cp.buyer_user_id)))
     LEFT JOIN public.organizations buyer_org ON ((buyer_org.id = cp.buyer_organization_id)))
     LEFT JOIN public.organizations seller_org ON ((seller_org.id = cp.seller_organization_id)))
     LEFT JOIN public.users seller_user ON ((seller_user.id = cp.seller_user_id)));


