    billing_interval text DEFAULT 'month'::text,
    sort_order integer DEFAULT 0,
    features jsonb DEFAULT '{}'::jsonb,
    stripe_price_id text,
    CONSTRAINT membership_tiers_billing_interval_check CHECK ((billing_interval = ANY (ARRAY['month'::text, 'year'::text, 'once'::text]))),
    CONSTRAINT membership_tiers_category_check CHECK ((category = ANY (ARRAY['service'::text, 'employee'::text, 'department'::text, 'os'::text, 'enterprise'::text]))),
    CONSTRAINT plan_tiers_key_check CHECK ((key ~ '^[a-z]+_[a-z_]+$'::text))
);


--
-- Name: clients_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.clients_readable WITH (security_invoker='on') AS
 SELECT c.id,
    c.full_name,
    c.email,
    c.business_name,
    c.client_type,
    c.plan_tier_key,
    mt.name AS plan_tier_name,
    c.status,
    c.onboarding_status,
    o.name AS organization_name,
    c.primary_vertical,
    c.total_spend,
    c.lifetime_value,
    c.vip_level,
    c.created_at,
    c.organization_id,
    c.auth_user_id
   FROM ((public.clients c
     LEFT JOIN public.organizations o ON ((o.id = c.organization_id)))
     LEFT JOIN public.membership_tiers mt ON ((mt.key = c.plan_tier_key)));


