--
-- Name: commissions_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.commissions_readable WITH (security_invoker='on') AS
 SELECT c.id,
    c.subscription_key,
    mt.name AS subscription_name,
    c.scope,
    c.catalog_item_id,
    ci.name AS catalog_item_name,
    c.ownership_type,
    c.commission_enabled,
    c.commission_value,
    c.recurring,
    c.cookie_days,
    c.payout_delay_days,
