);


--
-- Name: entitlements_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.entitlements_readable WITH (security_invoker='on') AS
 SELECT e.id,
    e.feature_key,
    e.feature_scope,
    e.limit_value,
    e.is_enabled,
    e.usage_count,
    e.source_type,
    e.starts_at,
    e.expires_at,
    o.name AS organization_name,
    o.plan_tier_key AS organization_plan_tier_key,
    o.tier AS organization_legacy_tier_field,
    u.email AS user_email,
    u.full_name AS user_full_name,
    e.organization_id,
    e.user_id,
    e.membership_id,
    e.created_at,
    e.updated_at
   FROM ((public.entitlements e
     LEFT JOIN public.organizations o ON ((o.id = e.organization_id)))
     LEFT JOIN public.users u ON ((u.id = e.user_id)));


