    is_organization,
    is_creator,
    price_range,
    price_sweet_spot,
    billing_interval,
    ( SELECT count(*) AS count
           FROM public.memberships m
          WHERE (m.membership_tier_id = mt.id)) AS real_membership_count,
    ( SELECT count(*) AS count
           FROM public.organizations o
          WHERE (o.plan_tier_key = mt.key)) AS organizations_on_this_tier,
    created_at,
    updated_at
   FROM public.membership_tiers mt;


