    CONSTRAINT os_activations_state_check CHECK ((state = ANY (ARRAY['passive'::text, 'active'::text, 'mastered'::text]))),
    CONSTRAINT os_activations_subject_check CHECK ((((organization_id IS NOT NULL) AND (user_id IS NULL)) OR ((organization_id IS NULL) AND (user_id IS NOT NULL)))),
    CONSTRAINT os_activations_tier_level_check CHECK ((tier_level = ANY (ARRAY['standard'::text, 'prime'::text, 'elite'::text]))),
    CONSTRAINT os_activations_trial_check CHECK ((((is_trial = false) AND (trial_ends_at IS NULL)) OR ((is_trial = true) AND (trial_ends_at IS NOT NULL))))
);


