CREATE VIEW public.organizations_readable WITH (security_invoker='on') AS
 SELECT o.id,
    o.name AS organization_name,
    o.slug,
    o.status,
    o.plan_tier_key,
    mt.name AS plan_tier_name,
    o.tier AS legacy_tier_field,
    owner.email AS owner_email,
    owner.full_name AS owner_full_name,
    o.subscription_status,
    o.created_at,
    o.updated_at,
    ( SELECT count(*) AS count
           FROM public.entitlements e
          WHERE (e.organization_id = o.id)) AS entitlement_row_count,
    ( SELECT count(*) AS count
           FROM public.os_activations oa
          WHERE (oa.organization_id = o.id)) AS os_activation_count
   FROM ((public.organizations o
     LEFT JOIN public.membership_tiers mt ON ((mt.key = o.plan_tier_key)))
     LEFT JOIN public.users owner ON ((owner.id = o.owner_id)));


