    cross_system_alignment numeric(6,2),
    escalation_frequency numeric(6,2),
    sii numeric(10,2) GENERATED ALWAYS AS (round(((((COALESCE(avg_mas, (0)::numeric) + COALESCE(bridge_efficiency, (0)::numeric)) + COALESCE(memory_integrity, (0)::numeric)) + COALESCE(cross_system_alignment, (0)::numeric)) - COALESCE(escalation_frequency, (0)::numeric)), 2)) STORED
);


