--
-- Name: tier_entitlements_readable; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tier_entitlements_readable WITH (security_invoker='on') AS
 SELECT te.id,
    te.plan_key,
    mt.name AS tier_name,
    mt.tier_type,
    mt.category AS membership_tier_category,
    mt.price_range,
    mt.status AS membership_tier_status,
    te.status AS tier_entitlements_status,
    mt.is_organization,
    mt.is_creator,
    te.max_agents,
    te.max_custom_agents,
    te.max_vertical_agents,
    te.max_swarms,
    te.max_swarm_capacity,
    te.max_workflows,
    te.max_workflow_runs_monthly,
    te.max_api_calls_monthly,
    te.max_storage_gb,
    te.max_memory_gbs,
    te.max_departments,
    te.max_businesses,
    te.max_members,
    te.max_locations,
    te.max_verticals,
    te.max_ai_twins,
    te.max_marketplace_products,
    te.max_courses,
    te.included_os_count,
    te.support_tier,
    te.level AS essence_level,
    ((mt.max_vertical_agents IS DISTINCT FROM te.max_vertical_agents) OR (mt.max_custom_agents IS DISTINCT FROM te.max_custom_agents) OR (mt.max_workflows IS DISTINCT FROM te.max_workflows) OR (mt.max_swarm_capacity IS DISTINCT FROM te.max_swarm_capacity) OR (mt.max_memory_gbs IS DISTINCT FROM te.max_memory_gbs)) AS mt_te_values_diverge,
    te.plan_key AS tier_key_raw
   FROM (public.tier_entitlements te
     LEFT JOIN public.membership_tiers mt ON ((mt.key = te.plan_key)));


